async function setTimetableStatus(id,nextStatus){if(role!=='admin'){message('Only authorised administrators can verify timetables.');return}const note=document.querySelector('[data-timetable-note="'+id+'"]')?.value||'';const update={status:nextStatus,review_note:note,verified_by:nextStatus==='verified'?user.id:null,verified_at:nextStatus==='verified'?new Date().toISOString():null,updated_at:new Date().toISOString()};const {data,error}=await db.from('academic_timetables').update(update).eq('id',id).select('id,status,verified_at').maybeSingle();if(error){message('Timetable status could not be updated: '+error.message);return}if(!data){message('No timetable status changed. Refresh and try again.');return}message(nextStatus==='verified'?'Timetable verified and now eligible to appear publicly.':nextStatus==='rejected'?'Timetable rejected.':'Timetable returned to pending verification.');await loadTimetables();renderOverview()}
async function saveTimetableNote(id){if(role!=='admin')return;const note=document.querySelector('[data-timetable-note="'+id+'"]')?.value||'';const {data,error}=await db.from('academic_timetables').update({review_note:note,updated_at:new Date().toISOString()}).eq('id',id).select('id').maybeSingle();if(error){message('Review note not saved: '+error.message);return}if(!data){message('No review note was changed.');return}message('Review note saved.');await loadTimetables()}
async function openTimetableEditor(){if(role!=='admin')return;$('timetable-form').reset();$('timetable-form-msg').textContent='';$('timetable-editor').showModal()}
async function submitTimetable(e){e.preventDefault();if(role!=='admin')return;const msg=$('timetable-form-msg'),btn=$('timetable-submit'),file=$('tt-file').files[0],url=$('tt-url').value.trim(),title=$('tt-title').value.trim(),programme=$('tt-programme').value,year=Number($('tt-year').value),semester=$('tt-semester').value,academicYear=$('tt-academic-year').value.trim(),description=$('tt-description').value.trim();if((!file&&!url)||(file&&url)){msg.textContent='Upload one PDF or provide one HTTPS URL, not both.';return}if(url&&!/^https:\/\//i.test(url)){msg.textContent='Timetable links must start with https://';return}if(!/^[0-9]{4}\/[0-9]{4}$/.test(academicYear)){msg.textContent='Use academic-year format YYYY/YYYY, for example 2026/2027.';return}let filePath='',fileName='External timetable link',fileSize=0,fileType='external/url';if(file){if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')){msg.textContent='Only PDF timetable uploads are accepted.';return}if(file.size>26214400){msg.textContent='The file must be 25 MB or smaller.';return}fileName=file.name;fileSize=file.size;fileType='application/pdf';const clean=file.name.replace(/[^A-Za-z0-9._-]/g,'_').slice(-94);filePath=crypto.randomUUID()+'/'+clean;msg.textContent='Uploading PDF…';const {error:uploadError}=await db.storage.from('academic-timetables').upload(filePath,file,{contentType:'application/pdf',upsert:false});if(uploadError){msg.textContent='Timetable upload failed: '+uploadError.message;return}}
btn.disabled=true;btn.textContent='Submitting…';msg.textContent='Saving as pending verification…';const payload={title,programme,year_of_study:year,semester,academic_year:academicYear,description,file_path:filePath,file_name:fileName,file_size:fileSize,file_type:fileType,file_url:url||null,status:'pending',verified_by:null,verified_at:null,review_note:null};const {data,error}=await db.from('academic_timetables').insert(payload).select('id,status').maybeSingle();if(error||!data){if(filePath){const {error:cleanError}=await db.storage.from('academic-timetables').remove([filePath]);if(cleanError)console.error('Timetable file cleanup failed',cleanError)}msg.textContent='Timetable could not be saved: '+(error?.message||'No record returned');btn.disabled=false;btn.textContent='Submit for verification';return}$('timetable-editor').close();btn.disabled=false;btn.textContent='Submit for verification';message('Timetable submitted as pending. It is not public until an authorised administrator verifies it.');await loadTimetables();renderOverview()}
async function openAdminTimetableFile(id){if(role!=='admin')return;const t=(cache.timetables||[]).find(x=>x.id===id);if(!t||!t.file_path)return;const tab=window.open('about:blank','_blank');if(!tab){message('Allow pop-ups to preview the timetable.');return}tab.opener=null;const {data,error}=await db.storage.from('academic-timetables').createSignedUrl(t.file_path,300);if(error||!data?.signedUrl){tab.close();message('Timetable preview failed: '+(error?.message||'Could not create secure link'));return}tab.location=data.signedUrl}

async function loadPartnerships(){if(role!=='admin'){$('partnerships-table').innerHTML='<p class="empty">Only administrators can review partnership proposals.</p>';return}const {data,error}=await db.from('partnership_submissions').select('*').order('created_at',{ascending:false}).limit(300);if(error){$('partnerships-table').innerHTML='<p class="empty">Could not load proposals: '+esc(error.message)+'</p>';return}cache.partnerships=data||[];renderPartnerships()}
