 const close=$('admin-project-upload-close'),cancel=$('admin-project-upload-cancel'),coverInput=$('admin-project-cover'),filesInput=$('admin-project-files'),coverPreview=$('admin-project-cover-preview'),filesList=$('admin-project-files-list'),msg=$('admin-project-upload-message'),submit=form.querySelector('[type=submit]');
 let cover=null,files=[],busy=false;const isImage=f=>['image/jpeg','image/png','image/webp'].includes(f.type)||/\.(jpe?g|png|webp)$/i.test(f.name),fmt=n=>n<1048576?Math.ceil(n/1024)+' KB':(n/1048576).toFixed(1)+' MB',say=t=>msg.textContent=t;
