 close.addEventListener('click',()=>{if(!busy)dialog.close()});cancel.addEventListener('click',()=>{if(!busy)dialog.close()});
 coverInput.addEventListener('change',()=>{const f=coverInput.files[0];if(!f)return;if(!isImage(f)||f.size>10485760){say('Choose JPG, PNG or WebP up to 10 MB.');coverInput.value='';cover=null;coverPreview.replaceChildren();return}cover=f;coverPreview.replaceChildren();const img=document.createElement('img');img.src=URL.createObjectURL(f);img.alt='Cover preview';img.style.cssText='max-width:100%;max-height:220px;object-fit:cover;border-radius:8px';coverPreview.append(img,document.createTextNode(f.name+' · '+fmt(f.size)))});
 function renderFiles(){filesList.replaceChildren();files.forEach((f,i)=>{const row=document.createElement('div');row.style.cssText='display:flex;justify-content:space-between;gap:12px;padding:6px 0';const label=document.createElement('span');label.textContent=f.name+' · '+fmt(f.size);const rm=document.createElement('button');rm.type='button';rm.className='secondary';rm.textContent='Remove';rm.onclick=()=>{files.splice(i,1);renderFiles()};row.append(label,rm);filesList.append(row)});const note=document.createElement('p');note.textContent=files.length+' / 20 files · '+fmt(files.reduce((n,f)=>n+f.size,0));filesList.append(note)}
 filesInput.addEventListener('change',()=>{for(const f of Array.from(filesInput.files)){if(!(isImage(f)||f.type==='application/pdf'||/\.pdf$/i.test(f.name))){say('Only PDF, JPG, PNG and WebP are allowed.');continue}if(f.size>20971520){say(f.name+' exceeds 20 MB.');continue}if(files.length>=20){say('Maximum 20 attachments.');break}if(files.reduce((n,x)=>n+x.size,0)+f.size>104857600){say('Total attachments limit is 100 MB.');break}if(!files.some(x=>x.name===f.name&&x.size===f.size&&x.lastModified===f.lastModified))files.push(f)}renderFiles();filesInput.value=''});
